#include <bits/stdc++.h>
using namespace std;
int main(){ int W,D,x,y,n; cin>>W>>D>>x>>y>>n; int dx[4]={1,0,-1,0}, dy[4]={0,1,0,-1}, d=0, dist=0;
  set<pair<int,int>> seen{{x,y}};
  for(int i=0;i<n;i++){ char T; int k; cin>>T>>k; if(T=='L') d=(d+1)%4; else if(T=='R') d=(d+3)%4;
    for(int s=0;s<k;s++){ x+=dx[d]; y+=dy[d]; dist++;
      if(x<0||x>W||y<0||y>D||seen.count({x,y})){ printf("%d\n(%d,%d) D\n",dist,x,y); return 0; } seen.insert({x,y}); } }
  printf("%d\n(%d,%d) A\n",dist,x,y); }
